// Récupérer les credentials depuis Node-RED (stockés chiffrés)
const clientId     = flow.get('google_client_id')     || env.get('GOOGLE_CLIENT_ID');
const clientSecret = flow.get('google_client_secret') || env.get('GOOGLE_CLIENT_SECRET');
const refreshToken = flow.get('google_refresh_token') || env.get('GOOGLE_REFRESH_TOKEN');

if (!clientId || !clientSecret || !refreshToken) {
  node.error('Credentials Google OAuth manquants. Configurer google_client_id, google_client_secret, google_refresh_token dans le context flow.', msg);
  return null;
}

msg.googleCreds = { clientId, clientSecret, refreshToken };

// Appel token endpoint Google
msg.payload = {
  client_id:     clientId,
  client_secret: clientSecret,
  refresh_token: refreshToken,
  grant_type:    'refresh_token'
};
msg.headers = { 'Content-Type': 'application/x-www-form-urlencoded' };
msg.method = 'POST';
msg.url = 'https://oauth2.googleapis.com/token';

// Encoder en x-www-form-urlencoded
const params = new URLSearchParams(msg.payload);
msg.payload = params.toString();

return msg;

if (!msg.payload.access_token) {
  node.error(`Échec OAuth Google : ${JSON.stringify(msg.payload)}`, msg);
  return null;
}

msg.accessToken = msg.payload.access_token;

// Date range : 7 derniers jours complets
const today = new Date();
today.setDate(today.getDate() - 1); // Hier (dernière date disponible dans GSC)
const endDate = today.toISOString().slice(0, 10);
const startDate = new Date(today.getTime() - 6 * 24 * 60 * 60 * 1000).toISOString().slice(0, 10);

msg.weekStart = startDate;
msg.weekEnd   = endDate;

const siteUrl = flow.get('gsc_site_url') || env.get('GSC_SITE_URL') || 'sc-domain:kpsyinformatique.com';
msg.gscSiteUrl = siteUrl;

// Requête GSC : top 50 mots-clés par clics
msg.payload = {
  startDate: startDate,
  endDate:   endDate,
  dimensions: ['query'],
  rowLimit:   50,
  startRow:   0
};

msg.headers = {
  'Authorization': `Bearer ${msg.accessToken}`,
  'Content-Type': 'application/json'
};

// URL encodée pour l'API GSC
const encodedSite = encodeURIComponent(siteUrl);
msg.url = `https://searchconsole.googleapis.com/webmasters/v3/sites/${encodedSite}/searchAnalytics/query`;

return msg;

if (msg.statusCode !== 200 || !msg.payload.rows) {
  node.error(`Erreur API GSC ${msg.statusCode}: ${JSON.stringify(msg.payload)}`, msg);
  return null;
}

const rows = msg.payload.rows;
const fs = require('fs');
const path = require('path');

// Formater les données de la semaine
const weekData = rows.map(r => ({
  keyword:     r.keys[0],
  clicks:      r.clicks,
  impressions: r.impressions,
  ctr:         Math.round(r.ctr * 10000) / 100,  // en %
  position:    Math.round(r.position * 10) / 10   // 1 décimale
}));

// Charger l'historique précédent
const historyFile = '/data/rankings/history.json';
let history = {};
try {
  if (fs.existsSync(historyFile)) {
    history = JSON.parse(fs.readFileSync(historyFile, 'utf8'));
  }
} catch(e) { node.warn('Pas d\'historique précédent — première exécution.'); }

// Détecter les baisses significatives
const threshold = parseInt(env.get('RANKING_ALERT_THRESHOLD') || '3');
const alerts = [];

weekData.forEach(item => {
  const prev = history[item.keyword];
  if (prev && (item.position - prev.position) > threshold) {
    alerts.push({
      keyword:   item.keyword,
      prevPos:   prev.position,
      currPos:   item.position,
      drop:      Math.round((item.position - prev.position) * 10) / 10
    });
  }
});

// Mettre à jour l'historique
weekData.forEach(item => {
  history[item.keyword] = { position: item.position, lastUpdated: msg.weekEnd };
});

msg.weekData     = weekData;
msg.alerts       = alerts;
msg.historyFile  = historyFile;
msg.historyToSave = JSON.stringify(history, null, 2);

node.log(`GSC: ${weekData.length} mots-clés traités, ${alerts.length} alertes`);
node.status({ fill: alerts.length ? 'red' : 'green', shape: 'dot', text: `${weekData.length} kw | ${alerts.length} alertes` });

return msg;

const fs = require('fs');
const path = require('path');

// Créer les dossiers si besoin
fs.mkdirSync('/data/rankings', { recursive: true });

// 1. Sauvegarder l'historique JSON
fs.writeFileSync(msg.historyFile, msg.historyToSave, 'utf8');

// 2. Ajouter au CSV mensuel
const csvFile = `/data/rankings/${msg.weekEnd.slice(0, 7)}.csv`;
const csvExists = fs.existsSync(csvFile);

const header = 'date,keyword,clicks,impressions,ctr_pct,position\n';
const rows = msg.weekData.map(r => 
  `${msg.weekEnd},"${r.keyword.replace(/"/g, '""')}",${r.clicks},${r.impressions},${r.ctr},${r.position}`
).join('\n');

if (!csvExists) {
  fs.writeFileSync(csvFile, header + rows + '\n', 'utf8');
} else {
  fs.appendFileSync(csvFile, rows + '\n', 'utf8');
}

node.log(`CSV mis à jour : ${csvFile}`);
return msg;

if (!msg.alerts || !msg.alerts.length) {
  node.status({ fill: 'green', shape: 'dot', text: 'Aucune alerte' });
  return null;  // Pas d'alerte → stop
}

// Construire le corps de l'email d'alerte
const alertList = msg.alerts.map(a =>
  `• "${a.keyword}" : position ${a.prevPos} → ${a.currPos} (−${a.drop} rangs)`
).join('\n');

msg.emailSubject = `⚠️ KPSy SEO — ${msg.alerts.length} mot(s)-clé(s) en baisse (${msg.weekEnd})`;
msg.emailBody = `Bonjour,\n\nL'analyse hebdomadaire Google Search Console de ${msg.weekEnd} a détecté les baisses suivantes :\n\n${alertList}\n\nSite surveillé : ${msg.gscSiteUrl}\nPériode analysée : ${msg.weekStart} → ${msg.weekEnd}\n\n→ Consulter le rapport complet dans /data/rankings/${msg.weekEnd.slice(0,7)}.csv\n\n---\nKPSy Automation | Node-RED`;

msg.payload = msg.emailBody;
msg.topic   = msg.emailSubject;

return msg;
